LOCK TABLES `village_events` WRITE;
/*!40000 ALTER TABLE `village_events` DISABLE KEYS */;
INSERT INTO `village_events` VALUES (1,1,'Festival Desa Adat Penglipuran','festival-desa-adat-penglipuran','<p>Festival tahunan yang menampilkan seluruh kekayaan budaya Desa Adat Penglipuran. Mulai dari pertunjukan tari tradisional Bali, lomba merangkai canang sari, hingga pameran kerajinan bambu khas desa.</p><p>Acara ini terbuka untuk umum dan menjadi ajang promosi budaya desa kepada wisatawan domestik maupun mancanegara. Selama festival berlangsung, seluruh jalan desa dihias dengan ornamen tradisional Bali yang indah.</p>','Balai Desa Adat Penglipuran','2026-06-03 02:17:40','2026-06-04 02:17:40','081234000001',1,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Festival+Desa+Adat+Penglipuran%2C+Desa+Adat+Penglipuran'),(2,1,'Upacara Ngusaba Desa Penglipuran','upacara-ngusaba-desa-penglipuran','<p>Upacara adat tahunan yang dilaksanakan sebagai bentuk rasa syukur atas hasil panen dan keselamatan desa. Seluruh warga desa berpartisipasi dalam prosesi upacara yang berlangsung di Pura Penataran Agung Penglipuran.</p><p>Wisatawan dipersilakan menyaksikan upacara dari jarak yang telah ditentukan dan diwajibkan mengenakan kain untuk memasuki area pura.</p>','Pura Penataran Agung Penglipuran','2026-08-02 02:17:40','2026-08-03 02:17:40','081234000001',0,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Upacara+Ngusaba+Desa+Penglipuran%2C+Desa+Adat+Penglipuran'),(3,2,'Pameran Tenun Ikat Sasak','pameran-tenun-ikat-sasak','<p>Pameran dan bursa tenun ikat khas suku Sasak yang menampilkan ratusan motif kain tenun tradisional. Para pengunjung dapat menyaksikan langsung proses pembuatan tenun menggunakan alat tradisional yang masih dipertahankan hingga kini.</p><p>Tersedia kelas workshop singkat untuk wisatawan yang ingin mencoba menenun sendiri dengan bimbingan pengrajin berpengalaman.</p>','Balai Komunitas Desa Sade','2026-06-18 02:17:40','2026-06-19 02:17:40','081234000002',1,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Pameran+Tenun+Ikat+Sasak%2C+Desa+Sade'),(4,2,'Perayaan Lebaran Topat Desa Sade','perayaan-lebaran-topat-desa-sade','<p>Tradisi unik suku Sasak yang dirayakan satu minggu setelah Idul Fitri. Seluruh warga membawa ketupat dan lauk pauk untuk bersama-sama makan di area terbuka. Suasana kebersamaan dan kekeluargaan begitu terasa dalam perayaan ini.</p>','Lapangan Desa Sade','2026-09-01 02:17:40','2026-09-04 02:17:40','081234000002',0,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Perayaan+Lebaran+Topat+Desa+Sade%2C+Desa+Sade'),(5,3,'Ritual Penti (Tahun Baru Wae Rebo)','ritual-penti-tahun-baru-wae-rebo','<p>Ritual Penti adalah upacara syukuran akhir tahun tradisional masyarakat Wae Rebo yang dilaksanakan setelah masa panen. Seluruh warga berkumpul di dalam Mbaru Niang utama untuk berdoa bersama, makan bersama, dan mengucap syukur kepada leluhur atas hasil bumi yang melimpah.</p><p>Ini adalah salah satu ritual paling sakral di Wae Rebo yang biasanya tidak boleh disaksikan oleh orang luar selain tamu undangan. Namun, pihak desa kadang membuka kesempatan bagi wisatawan khusus untuk menyaksikannya dari kejauhan.</p>','Mbaru Niang Utama, Desa Wae Rebo','2026-07-03 02:17:40','2026-07-06 02:17:40','081234000003',1,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Ritual+Penti+%28Tahun+Baru+Wae+Rebo%29%2C+Desa+Wae+Rebo'),(6,4,'Dieng Culture Festival (DCF)','dieng-culture-festival-dcf','<p>Festival budaya terbesar di Dataran Tinggi Dieng yang menampilkan puncak acara berupa ritual Pemotongan Rambut Gimbal anak-anak Dieng. Festival ini juga menampilkan pertunjukan wayang kulit, jazz di atas awan, dan berbagai pertunjukan seni budaya lokal.</p><p>DCF telah menjadi salah satu festival pariwisata paling populer di Indonesia dan menarik ribuan wisatawan dari seluruh nusantara bahkan mancanegara setiap tahunnya.</p>','Kompleks Candi Arjuna, Dieng','2026-07-18 02:17:40','2026-07-19 02:17:40','081234000004',1,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Dieng+Culture+Festival+%28DCF%29%2C+Desa+Wisata+Dieng+Kulon'),(7,4,'Pasar Malam Agrowisata Dieng','pasar-malam-agrowisata-dieng','<p>Pasar malam yang menampilkan berbagai produk agrowisata Dieng, mulai dari kentang, carica, purwaceng, hingga berbagai produk olahan khas dataran tinggi Dieng. Dilengkapi dengan hiburan live musik tradisional dan kuliner khas Wonosobo.</p>','Alun-alun Dieng Kulon','2026-05-19 02:17:40','2026-05-21 02:17:40','081234000004',0,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Pasar+Malam+Agrowisata+Dieng%2C+Desa+Wisata+Dieng+Kulon'),(8,5,'Odalan Pura Pancering Jagat','odalan-pura-pancering-jagat','<p>Upacara odalan (hari jadi pura) yang dilaksanakan setiap 210 hari sekali berdasarkan kalender Bali Pawukon. Upacara ini adalah yang paling sakral dan meriah di Desa Trunyan, melibatkan seluruh warga dan berlangsung selama beberapa hari.</p><p>Wisatawan yang tertarik dapat menyaksikan rangkaian upacara dari luar area pura dengan mengenakan pakaian yang sopan dan selendang.</p>','Pura Pancering Jagat, Trunyan','2026-08-17 02:17:40','2026-08-20 02:17:40','081234000005',1,'2026-05-03 19:17:40','2026-05-03 19:17:40','https://maps.google.com/?q=Odalan+Pura+Pancering+Jagat%2C+Desa+Trunyan');
/*!40000 ALTER TABLE `village_events` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `villages`
