LOCK TABLES `villages` WRITE;
/*!40000 ALTER TABLE `villages` DISABLE KEYS */;
INSERT INTO `villages` VALUES (1,2,'Desa Adat Penglipuran','desa-adat-penglipuran','Desa adat terbersih di dunia terletak di Bangli, Bali, dengan arsitektur tradisional yang terjaga.','<p>Desa Adat Penglipuran adalah salah satu desa tradisional Bali yang terkenal sebagai salah satu desa terbersih di dunia. Terletak di Kabupaten Bangli, desa ini mempertahankan tata ruang dan arsitektur tradisional Bali secara konsisten sejak ratusan tahun lalu.</p><p>Setiap rumah di Penglipuran memiliki pintu gerbang (angkul-angkul) yang seragam, menciptakan pemandangan yang sangat estetis dan harmonis. Hutan bambu yang lebat di belakang desa menjadi penyangga ekosistem yang dijaga ketat oleh masyarakat adat setempat.</p><p>Pengunjung dapat menikmati suasana pedesaan Bali yang autentik, mempelajari adat istiadat lokal, serta mencicipi kuliner khas seperti loloh cemcem dan minuman tradisional lainnya.</p><p>Desa ini juga aktif menyelenggarakan berbagai kegiatan budaya dan upacara adat yang berkaitan dengan siklus pertanian dan kepercayaan Hindu Bali.</p>','budaya_tradisi','Jl. Penglipuran, Desa Kubu, Kec. Bangli, Kab. Bangli, Bali 80613',-8.41090000,115.35900000,'https://maps.google.com/?q=-8.4109,115.3590','verified',1,NULL,'2026-05-03 19:17:39','2026-05-03 19:17:39'),(2,3,'Desa Sade','desa-sade','Desa tradisional suku Sasak di Lombok dengan rumah beratap ilalang dan ritual adat yang masih terjaga.','<p>Desa Sade adalah desa adat suku Sasak yang terletak di Kecamatan Pujut, Kabupaten Lombok Tengah, Nusa Tenggara Barat. Desa ini merupakan salah satu dari sedikit desa yang masih mempertahankan kehidupan tradisional suku Sasak secara autentik.</p><p>Rumah-rumah di Desa Sade memiliki ciri khas berupa lantai yang dipel menggunakan kotoran kerbau yang digunakan secara tradisional karena dipercaya memiliki khasiat tertentu dan membuat lantai mengeras. Atap rumah terbuat dari ilalang yang diganti setiap beberapa tahun sekali.</p><p>Pengunjung dapat menyaksikan langsung proses pembuatan kain tenun ikat Sasak, salah satu warisan budaya yang masih dilestarikan oleh para ibu dan perempuan di desa ini. Motif-motif tenun Sasak memiliki nilai filosofis yang dalam.</p><p>Ritual adat dan perkawinan tradisional Sasak juga masih dilaksanakan, menjadikan Desa Sade destinasi budaya yang sangat berharga bagi wisatawan yang ingin memahami kebudayaan Lombok lebih dalam.</p>','budaya_tradisi','Desa Rembitan, Kec. Pujut, Kab. Lombok Tengah, NTB 83573',-8.86670000,116.23330000,'https://maps.google.com/?q=-8.8667,116.2333','verified',1,NULL,'2026-05-03 19:17:39','2026-05-03 19:17:39'),(3,4,'Desa Wae Rebo','desa-wae-rebo','Desa adat terpencil di atas pegunungan Manggarai, NTT, dengan rumah adat Mbaru Niang berbentuk kerucut.','<p>Desa Wae Rebo adalah sebuah desa adat yang tersembunyi di dalam hutan pegunungan Manggarai, Flores, Nusa Tenggara Timur. Terletak di ketinggian sekitar 1.200 meter di atas permukaan laut, desa ini hanya bisa dicapai dengan trekking selama 3-4 jam dari Desa Denge.</p><p>Keunikan utama Wae Rebo adalah tujuh rumah adat Mbaru Niang yang berbentuk kerucut menjulang setinggi sekitar 15 meter. Semua rumah ini dibangun menggunakan material alami dari hutan sekitar dan dipertahankan sesuai dengan aturan adat yang ketat.</p><p>UNESCO memberikan penghargaan kepada Wae Rebo atas keberhasilan masyarakat setempat dalam merevitalisasi dan mempertahankan arsitektur tradisional mereka. Ini menjadikan Wae Rebo sebagai contoh sukses pelestarian warisan budaya tingkat dunia.</p><p>Pengunjung yang menginap di Wae Rebo akan mendapatkan pengalaman hidup bersama masyarakat adat, menikmati masakan tradisional, dan menyaksikan ritual-ritual adat yang masih dijaga dengan penuh kekhusyukan.</p>','budaya_tradisi','Desa Satar Lenda, Kec. Satar Mese Barat, Kab. Manggarai, NTT 86562',-8.68330000,120.36670000,'https://maps.google.com/?q=-8.6833,120.3667','verified',0,NULL,'2026-05-03 19:17:39','2026-05-03 19:17:39'),(4,5,'Desa Wisata Dieng Kulon','desa-wisata-dieng-kulon','Desa di dataran tinggi Dieng yang menawarkan keindahan alam pegunungan, candi Hindu kuno, dan fenomena alam unik.','<p>Desa Wisata Dieng Kulon berada di kawasan Dataran Tinggi Dieng, Kabupaten Wonosobo, Jawa Tengah, pada ketinggian sekitar 2.093 meter di atas permukaan laut. Kawasan ini dikenal sebagai \"Negeri di Atas Awan\" karena pemandangan awan yang sering menyelimuti lembah dan gunung di sekitarnya.</p><p>Dataran Tinggi Dieng merupakan kawasan vulkanik aktif yang menyimpan berbagai keajaiban alam sekaligus peninggalan sejarah yang luar biasa. Kompleks candi Hindu dari Abad ke-7 hingga ke-9 Masehi menjadi salah satu daya tarik arkeologi terpenting di Jawa.</p><p>Fenomena alam yang paling terkenal adalah kawah-kawah aktif seperti Kawah Sikidang dan Kawah Candradimuka, serta Telaga Warna yang memiliki warna air yang berubah-ubah karena kandungan belerang dan mineral tertentu.</p><p>Ritual Pemotongan Rambut Gimbal anak-anak Dieng adalah tradisi unik yang menarik ribuan wisatawan setiap tahunnya. Anak-anak berambut gimbal (rambut yang tumbuh menggumpal secara alami) dipercaya memiliki kekuatan spiritual khusus dan pemotongan rambutnya dilakukan dalam upacara adat yang meriah.</p>','budaya_tradisi','Desa Dieng Kulon, Kec. Batur, Kab. Banjarnegara, Jawa Tengah 53456',-7.20970000,109.91750000,'https://maps.google.com/?q=-7.2097,109.9175','verified',1,NULL,'2026-05-03 19:17:39','2026-05-03 19:17:39'),(5,6,'Desa Trunyan','desa-trunyan','Desa kuno di tepi Danau Batur, Bali, terkenal dengan tradisi pemakaman unik di bawah pohon Taru Menyan.','<p>Desa Trunyan adalah desa kuno Bali Aga yang terletak di tepi barat Danau Batur, Kecamatan Kintamani, Kabupaten Bangli, Bali. Desa ini dihuni oleh suku Bali Aga, yaitu penduduk asli Bali sebelum masuknya pengaruh Hindu dari Jawa.</p><p>Tradisi paling terkenal dari Desa Trunyan adalah cara pemakaman yang sangat unik. Jenazah orang yang meninggal tidak dikubur atau dibakar (ngaben), melainkan diletakkan begitu saja di bawah pohon Taru Menyan yang sudah berusia ratusan tahun. Keunikannya, meski jenazah dibiarkan di alam terbuka, pohon Taru Menyan mengeluarkan aroma harum yang mengorbankan bau busuk dari proses pembusukan jenazah.</p><p>Selain tradisi pemakaman, Desa Trunyan memiliki Pura Pancering Jagat, salah satu pura tertua dan paling keramat di Bali yang dipersembahkan kepada Dewa Ratu Gede Pancering Jagat. Upacara keagamaan di pura ini selalu berlangsung dengan hikmat dan penuh warna.</p><p>Akses ke Desa Trunyan hanya bisa melalui perahu menyeberangi Danau Batur, menambah kesan petualangan bagi setiap wisatawan yang berkunjung.</p>','budaya_tradisi','Desa Trunyan, Kec. Kintamani, Kab. Bangli, Bali 80652',-8.25610000,115.41430000,'https://maps.google.com/?q=-8.2561,115.4143','verified',0,NULL,'2026-05-03 19:17:39','2026-05-03 19:17:39'),(6,7,'Desa Wisata Kemiren','desa-wisata-kemiren','Desa adat suku Osing di Banyuwangi yang kaya seni budaya, ritual tradisional, dan kerajinan tangan khas.','<p>Desa Wisata Kemiren terletak di Kecamatan Glagah, Kabupaten Banyuwangi, Jawa Timur. Desa ini merupakan sentra kebudayaan suku Osing, suku asli Banyuwangi yang memiliki bahasa, seni, dan tradisi yang berbeda dari suku Jawa maupun Bali.</p><p>Kesenian khas suku Osing yang paling terkenal adalah Tari Gandrung, tarian seremonial yang melambangkan rasa syukur setelah panen dan telah menjadi ikon budaya Banyuwangi. Setiap tahun, Festival Gandrung Sewu menampilkan ribuan penari Gandrung secara bersamaan di pantai Banyuwangi.</p><p>Ritual Barong Ider Bumi yang dilaksanakan setiap tanggal 2 Syawal adalah tradisi unik yang bertujuan untuk menolak bala dan menjaga keselamatan warga desa. Prosesi ini melibatkan seluruh warga desa dan berlangsung sangat meriah.</p><p>Rumah adat suku Osing di Kemiren memiliki ciri khas berupa teras depan terbuka yang disebut \"serambi\" dan penggunaan material kayu yang dominan. Para pengunjung dapat menyaksikan langsung pembuatan batik Using dan kerajinan anyaman bambu.','budaya_tradisi','Desa Kemiren, Kec. Glagah, Kab. Banyuwangi, Jawa Timur 68453',-8.21690000,114.35860000,'https://maps.google.com/?q=-8.2169,114.3586','pending',0,NULL,'2026-05-03 19:17:39','2026-05-03 19:17:39');
